#include <numeric>
#include <thread>
#include <vector>

long long parallelSum(const std::vector<int>& values, unsigned parts)
{
    std::vector<long long> partial(parts, 0);
    const std::size_t chunk{ values.size() / parts };
    {
        std::vector<std::jthread> threads{};
        for (unsigned p{ 0 }; p < parts; ++p)
        {
            const auto first{ values.begin() + static_cast<std::ptrdiff_t>(p * chunk) };
            const auto last{ p + 1 == parts ? values.end() : first + static_cast<std::ptrdiff_t>(chunk) };
            threads.emplace_back([first, last, &partial, p] { partial[p] = std::accumulate(first, last, 0LL); });
        }
    }
    return std::accumulate(partial.begin(), partial.end(), 0LL);
}

unitTests:
std::vector<int> upTo(int n) { std::vector<int> v(static_cast<std::size_t>(n)); std::iota(v.begin(), v.end(), 1); return v; }
TEST("matches the ordinary sum") { CHECK_EQ(parallelSum(upTo(1000), 4), 500500LL); CHECK_EQ(parallelSum(upTo(1000), 1), 500500LL); }
TEST("sizes that do not divide evenly") { CHECK_EQ(parallelSum(upTo(1003), 4), 503506LL); CHECK_EQ(parallelSum(upTo(10), 3), 55LL); CHECK_EQ(parallelSum(upTo(7), 7), 28LL); }
TEST("more parts than elements, and no elements") { CHECK_EQ(parallelSum(upTo(3), 8), 6LL); CHECK_EQ(parallelSum({}, 4), 0LL); }
TEST("values too big for an int total") { const std::vector<int> big(100000, 2000000000); CHECK_EQ(parallelSum(big, 8), 200000000000000LL); }

